package movie.sources;
import android.app.*;import android.os.*;import android.content.*;import android.view.accessibility.*;import android.graphics.Bitmap;
import com.mgs.carparking.modern.core.Legacy;
import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;

/** End-to-end native player checks on the disposable emulator; does not contact HDO. */
public final class SourceUiCheck extends Instrumentation {
 Activity current;Object controller;JSONObject report=new JSONObject();File dir;int id=185909106;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void callActivityOnResume(Activity a){super.callActivityOnResume(a);current=a;}
 void main(Runnable r){Throwable[] error={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){error[0]=t;}});if(error[0]!=null)throw new IllegalStateException(error[0]);}
 Object exo(){return Legacy.call(Legacy.field(current,"f"),"D");}
 AccessibilityNodeInfo node(AccessibilityNodeInfo n,String text){if(n==null)return null;CharSequence s=n.getText(),d=n.getContentDescription();if(s!=null&&s.toString().contains(text)||d!=null&&d.toString().contains(text))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=node(n.getChild(i),text);if(child!=null)return child;}return null;}
 void await(String text,int seconds)throws Exception{for(int i=0;i<seconds*2;i++){if(node(getUiAutomation().getRootInActiveWindow(),text)!=null)return;Thread.sleep(500);}throw new AssertionError("Missing UI: "+text);}
 void click(String text)throws Exception{await(text,3);AccessibilityNodeInfo n=node(getUiAutomation().getRootInActiveWindow(),text);while(n!=null&&!n.isClickable())n=n.getParent();if(n==null||!n.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new AssertionError("UI click failed");Thread.sleep(300);}
 AccessibilityNodeInfo scrollable(AccessibilityNodeInfo n){if(n==null)return null;if(n.isScrollable())return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo result=scrollable(n.getChild(i));if(result!=null)return result;}return null;}
 void reveal(String text)throws Exception{for(int i=0;i<8&&node(getUiAutomation().getRootInActiveWindow(),text)==null;i++){AccessibilityNodeInfo list=scrollable(getUiAutomation().getRootInActiveWindow());if(list==null)break;list.performAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD);Thread.sleep(350);}await(text,3);}
 void shot(String name)throws Exception{Bitmap b=getUiAutomation().takeScreenshot();try(OutputStream o=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,o);}b.recycle();}
 JSONObject sample()throws Exception{final JSONObject[] out={null};main(()->{try{Object p=exo(),f=Legacy.field(p,"r"),c=Legacy.field(p,"B");if(c!=null)Legacy.call(c,"a");out[0]=new JSONObject().put("state",Legacy.integer(p,"getPlaybackState")).put("position_ms",Legacy.number(p,"getCurrentPosition")).put("width",f==null?0:Legacy.field(f,"n")).put("height",f==null?0:Legacy.field(f,"o")).put("frames",c==null?0:Legacy.field(c,"e"));}catch(Exception e){throw new IllegalStateException(e);}});return out[0];}
 JSONObject playing(int minHeight,int timeout)throws Exception{int first=-1,lastHeight=0;for(int i=0;i<timeout/2;i++){Thread.sleep(2000);try{JSONObject s=sample();int h=s.getInt("height");if(h!=lastHeight){lastHeight=h;first=s.getInt("frames");}if(h>=minHeight&&s.getInt("state")==3&&first>=0&&s.getInt("frames")-first>30)return s.put("pss_kib",android.os.Debug.getPss());}catch(RuntimeException ignored){}}throw new AssertionError("No sustained playback");}
 void startPlayer(){startActivitySync(new Intent().setClassName(getTargetContext(),"com.mgs.carparking.ui.homecontent.videodetail.VideoPlayDetailActivity").putExtra("id",id).putExtra("language_type",2).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 public void onStart(){Bundle result=new Bundle();try{
  dir=new File(getTargetContext().getFilesDir(),"source-ui-proof");dir.mkdirs();Files.deleteIfExists(new File(dir,"error-private.txt").toPath());
  startActivitySync(new Intent().setClassName(getTargetContext(),"com.mgs.carparking.ui.login.splash.SplashActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  for(int i=0;i<80;i++){if(current!=null&&current.getClass().getName().endsWith("ProfilesActivity")){Object p=Legacy.call(Legacy.type("com.mgs.carparking.modern.profiles.Profiles"),"get",getTargetContext());Object active=Legacy.call(p,"active");click("Perfil: "+Legacy.field(active,"name"));}if(current!=null&&current.getClass().getName().endsWith("HomeActivity"))break;Thread.sleep(500);}
  Legacy.call(Legacy.type("com.mgs.carparking.modern.catalog.Catalog"),"bootstrap",getTargetContext());Legacy.call(Legacy.type("com.mgs.carparking.modern.catalog.Catalog"),"awaitPlayback");
  startPlayer();JSONObject catalog=playing(360,65);report.put("catalog_before",catalog);Object originalExo=exo();
  controller=((Map<?,?>)Legacy.field(Legacy.type("com.mgs.carparking.modern.player.PlayerUi"),"ACTIVE")).get(current);if(controller==null)throw new AssertionError("Native controls unavailable");
  main(()->Legacy.call(controller,"sources"));await("Fontes de reprodução",3);shot("fontes-catalogo");click(node(getUiAutomation().getRootInActiveWindow(),"Encontrar fontes adicionais")!=null?"Encontrar fontes adicionais":"Alterar identificação da obra");await("TMDB · 76600",30);shot("identificar-obra");click("TMDB · 76600");await("Escolha uma fonte",5);shot("provedores");click("HuntStream");await("Fonte encontrada",40);shot("fonte-encontrada");click("Reproduzir · HuntStream");
  JSONObject external=playing(1080,60);report.put("external_playback",external).put("same_exo",originalExo==exo());if(originalExo!=exo())throw new AssertionError("Engine replaced");
  main(()->Legacy.call(controller,"quality"));await("Automático",3);shot("qualidade");click("Fechar painel");
  main(()->Legacy.call(controller,"languages"));await("Idioma e legendas",3);shot("audio-legendas");Object panel=Legacy.field(controller,"panel");for(Object row:(List<?>)Legacy.field(panel,"choices"))if("Versão · Dublado".equals(Legacy.field(row,"title"))&&Boolean.TRUE.equals(Legacy.field(row,"selected")))throw new AssertionError("Catalog dubbing falsely marked as active external audio");report.put("external_audio_does_not_claim_catalog_dubbing",true);click("Fechar painel");
  main(()->Legacy.call(controller,"sources"));click("Fontes adicionais ·");await("Escolha uma fonte",5);reveal("NovaStream");click("NovaStream");await("Fonte encontrada",40);click("Reproduzir · NovaStream");JSONObject nova=playing(360,60);Object activeSource=Legacy.field(controller,"external");if(activeSource==null||!"NovaStream".equals(Legacy.field(activeSource,"provider"))||!"dash".equals(Legacy.field(activeSource,"mediaType")))throw new AssertionError("DASH source was not installed in native player");report.put("nova_ui_playback",nova).put("same_exo_after_dash",originalExo==exo());if(nova.getLong("position_ms")<external.getLong("position_ms")-1500)throw new AssertionError("DASH switch lost position");
  main(()->Legacy.call(controller,"languages"));await("Idioma e legendas",3);shot("audio-dash");Activity externalActivity=current;click("Versão · Dublado");for(int i=0;i<60&&current==externalActivity;i++)Thread.sleep(100);JSONObject returned=playing(360,60);controller=((Map<?,?>)Legacy.field(Legacy.type("com.mgs.carparking.modern.player.PlayerUi"),"ACTIVE")).get(current);report.put("catalog_returned",returned).put("catalog_reopened_normally",current!=externalActivity);if(controller==null||Legacy.field(controller,"external")!=null||Legacy.integer(Legacy.field(current,"g"),"getAudio_type")!=2)throw new AssertionError("Dublado did not restore actual catalog source");if(returned.getLong("position_ms")<nova.getLong("position_ms")-1500)throw new AssertionError("Source switch lost position");
  Object profiles=Legacy.call(Legacy.type("com.mgs.carparking.modern.profiles.Profiles"),"get",getTargetContext());main(()->{Legacy.call(controller,"save");Legacy.call(profiles,"flush");});Object progress=Legacy.call(profiles,"progress",id);if(progress==null)throw new AssertionError("Catalog history missing");long saved=((Number)Legacy.field(progress,"position")).longValue();report.put("saved_catalog_id",Legacy.field(progress,"id")).put("saved_position_ms",saved);
  Object backup=Legacy.type("com.mgs.carparking.modern.profiles.Backup");byte[] data=(byte[])Legacy.call(backup,"exportData",getTargetContext());JSONObject tampered=new JSONObject(new String(data,"UTF-8"));JSONArray rows=tampered.getJSONArray("profiles");boolean tested=false;
  for(int i=0;i<rows.length();i++){JSONObject binding=rows.getJSONObject(i).getJSONObject("preferences").optJSONObject("source_identities");if(binding!=null&&binding.length()>0){binding.getJSONObject(binding.keys().next()).put("url","https://invalid.example/not-a-stored-source");tested=true;break;}}
  if(!tested)throw new AssertionError("Source binding missing from backup");boolean rejected=false;try{Legacy.call(backup,"restoreData",getTargetContext(),tampered.toString().getBytes("UTF-8"));}catch(IllegalStateException expected){rejected=true;}if(!rejected)throw new AssertionError("Unknown source binding field accepted");report.put("invalid_source_backup_rejected",true);
  Legacy.call(backup,"restoreData",getTargetContext(),data);JSONObject restored=(JSONObject)Legacy.field(Legacy.call(profiles,"active"),"preferences");JSONObject binding=restored.getJSONObject("source_identities").getJSONObject(id+"_0");if(binding.getInt("id")!=76600)throw new AssertionError("Source identity was not restored");report.put("source_identity_backup_restored",true);
  main(()->current.finish());Thread.sleep(1000);startPlayer();JSONObject resumed=playing(360,60);report.put("resumed",resumed);if(resumed.getLong("position_ms")<saved-1500)throw new AssertionError("Resume failed");
  report.put("passed",true);result.putString("result","PASS");
 }catch(Throwable t){result.putString("result","FAIL");try{report.put("error_class",t.getClass().getSimpleName());try(PrintWriter p=new PrintWriter(new File(dir,"error-private.txt"))){t.printStackTrace(p);}shot("failure");}catch(Exception ignored){}}
 finally{try{Files.write(new File(dir,"result-public.json").toPath(),report.toString(2).getBytes("UTF-8"));}catch(Exception ignored){}result.putString("report",report.toString());finish(Activity.RESULT_OK,result);}}
}
